const M = 10, N = M;
let path = [], p;

function setup() {
  createCanvas(500, 500, WEBGL);
	pixelDensity(1);

  p = [2*~~random(M/2), 2*~~random(N/2)]; // starting point
}

function draw() {
	background("#fffbe6");
  translate(-width/2, -height/2);

  let eventualNeighbors = possibleNeighbors(p, M, N);

	let i = p[0], j = p[1];
	if (i < M-2 && (j > 0 && inArray([i+1, j-1], path)) && inArray([i+1, j], path) && (j < N-1 && inArray([i+1, j+1], path))) {
		eventualNeighbors.push([i+2, j]);
	}
	if (i > 1 && (j > 0 && inArray([i-1, j-1], path)) && inArray([i-1, j], path) && (j < N-1 && inArray([i-1, j+1], path))) {
		eventualNeighbors.push([i-2, j]);
	}
	if (j < N-2 && (i > 0 && inArray([i-1, j+1], path)) && inArray([i, j+1], path) && (i < M-1 && inArray([i+1, j+1], path))) {
		eventualNeighbors.push([i, j+2]);
	}
	if (j > 1 && (i > 0 && inArray([i-1, j-1], path)) && inArray([i, j-1], path) && (i < M-1 && inArray([i+1, j-1], path))) {
		eventualNeighbors.push([i, j-2]);
	}

  shuffle(eventualNeighbors, true);

  let neighbors = [[], []];
  for (let neigh of eventualNeighbors) {
    let projectedPath = [...path, p, neigh];
    let count = countDeadends(projectedPath, possibleNeighbors(neigh, M, N), M, N);
    if (!inArray(neigh, path) && !disjointed(projectedPath, M, N) && count < 2 && !cursedCorners(projectedPath, M, N)) {
      neighbors[count].push(neigh);
    }
  }
  neighbors = neighbors.flat(1);

  let _wG_1 = 0; while ((neighbors.length == 0) && ++_wG_1 < 20000) {
    // backtracking
    let previous = path.pop();
    p = [previous[0], previous[1]];
    neighbors = previous[2];
  }

  let pNext = neighbors.shift();
  path.push([...p, neighbors]);
  p = pNext;

	let drawnPath = getDrawnPath(path, p);

  let margin = 50;
	let palette = ["#ef562f", "#f9d531", "#a7cc51", "#4bafdd", "#bd4ee5"], colIdx;
	//palette = ["#f398c3", "#f44e24", "#f4d730", "#23b247", "#2a76d3"]
	//palette = ["#ef562f", "#fc8405", "#f9d531", "#a7cc51", "#4bafdd"];
	let c = 1/(2*palette.length), inter = c/4;
	let aStep = (1-2*c)/palette.length;
	for (let k = 0; k < drawnPath.length; k++) {
		colIdx = 0;
		for (let a = c; a < 1-c-0.01; a += (Math.max(0.001, Math.abs(aStep)) || 1)) {
			drawPathPortion(drawnPath, k, margin, margin, width-2*margin, height-2*margin, M, N, 5, a-inter, 1-a-aStep-inter, c-inter*2);
			drawPathPortion(drawnPath, k, margin, margin, width-2*margin, height-2*margin, M, N, palette[colIdx++], a+inter, 1-a-aStep+inter, c);
		}
	}

  if (path.length == M*N-1) {
    //path.push(p);
    //console.log(frameCount);
    // noLoop() removed for animation
  }
}

// computing

function possibleNeighbors([i, j], m, n) {
  let possibilities = [];
  if (j < n-1) possibilities.push([i, j+1]);
  if (j > 0) possibilities.push([i, j-1]);
  if (i < m-1) possibilities.push([i+1, j]);
  if (i > 0) possibilities.push([i-1, j]);
  return possibilities;
}

function inArray([i, j], arr) {
  for (let e of arr) {
    if (e[0] == i && e[1] == j) return true;
  }
  return false;
}

// does arr disjoint the m*n grid?
function disjointed(arr, m, n) {
  if (arr.length >= m*n) {
    return false;
  }

  // choose initial point
  let p;
  do {
    p = [~~random(m), ~~random(n)];
  } while (inArray(p, arr))

  // traverse the m*n grid where arr was removed, through a DFS
  let discovered = [];
  let stack = [p];
  let _wG_2 = 0; while ((stack.length > 0) && ++_wG_2 < 20000) {
    p = stack.pop();
    if (!inArray(p, discovered)) {
      discovered.push(p);
      var neighbors = possibleNeighbors(p, m, n);
      for (let neigh of neighbors) {
        if (!inArray(neigh, arr)) stack.push(neigh);
      }
    }
  }

  return discovered.length != m*n-arr.length;
}

function countDeadends(arr, ignoreMe, m, n) {
  var count = 0;
  for (let i = 0; i < m; i++) {
    for (let j = 0; j < n; j++) {
      if (!inArray([i, j], arr) && !inArray([i, j], ignoreMe)) {
        var eventualNeighbors = possibleNeighbors([i, j], m, n);
        var neighbors = [];
        for (let neigh of eventualNeighbors) {
          if (!inArray(neigh, arr)) neighbors.push(neigh);
        }
        if (neighbors.length < 2) {
          count++;
        }
      }
    }
  }
  return count;
}

function cursedCorners(arr, M, N) {
  let corner1 = !inArray([0, 0], arr) && !inArray([1, 0], arr) && !inArray([0, 1], arr) && !inArray([1, 1], arr) && !inArray([2, 0], arr) && !inArray([0, 2], arr) && inArray([2, 1], arr) && inArray([1, 2], arr) && inArray([2, 2], arr);
  let corner2 = !inArray([M-1, 0], arr) && !inArray([M-2, 0], arr) && !inArray([M-1, 1], arr) && !inArray([M-2, 1], arr) && !inArray([M-3, 0], arr) && !inArray([M-1, 2], arr) && inArray([M-3, 1], arr) && inArray([M-2, 2], arr) && inArray([M-3, 2], arr);
  let corner3 = !inArray([M-1, N-1], arr) && !inArray([M-2, N-1], arr) && !inArray([M-1, N-2], arr) && !inArray([M-2, N-2], arr) && !inArray([M-3, N-1], arr) && !inArray([M-1, N-3], arr) && inArray([M-3, N-2], arr) && inArray([M-2, N-3], arr) && inArray([M-3, N-3], arr);
  let corner4 = !inArray([0, N-1], arr) && !inArray([1, N-1], arr) && !inArray([0, N-2], arr) && !inArray([1, N-2], arr) && !inArray([2, N-1], arr) && !inArray([0, N-3], arr) && inArray([2, N-2], arr) && inArray([1, N-3], arr) && inArray([2, N-3], arr);

  return corner1 || corner2 || corner3 || corner4;
}

function connected(arr, e1, e2) {
	for (let k = 0; k < arr.length-1; k++) {
		let a1 = arr[k], a2 = arr[k+1];
		if (((a1[0] == e1[0] && a1[1] == e1[1]) && (a2[0] == e2[0] && a2[1] == e2[1])) || ((a2[0] == e1[0] && a2[1] == e1[1]) && (a1[0] == e2[0] && a1[1] == e2[1])))
			return true;
	}
	return false;
}

// drawing

function getDrawnPath(path, p) {
	var drawnPath = [];
	for (let k = 0; k < path.length-1; k++) {
		let p0 = path[k], p1 = path[k+1];
		drawnPath.push(p0);
		if (abs(p0[0]-p1[0]) > 1 || abs(p0[1]-p1[1]) > 1) {
			drawnPath.push([(p0[0]+p1[0])/2, (p0[1]+p1[1])/2]);
		}
	}
	drawnPath.push(path[path.length-1]);
	drawnPath.push(p);
	return drawnPath;
}

function getDirection(pA, pB) {
  if (pA[0] == pB[0]) {
    if (pA[1] > pB[1]) return "down";
    else return "up";
  } else {
    if (pA[0] > pB[0]) return "right";
    else return "left";
  }
}

function drawExtremity(path, start, sx, sy, a, b, c) {
	var i = 0, j = 1;
	if (!start) {
		i = path.length-1;
		j = path.length-2;
	}
  var p0 = path[i];
  let p1 = path[j];
  let dir = getDirection(p0, p1);
  if (dir == "down") {
		if (start) rect((p0[0]+a)*sx, p0[1]*sy, (1-a-b)*sx, (1-c)*sy);
		else rect((p0[0]+b)*sx, p0[1]*sy, (1-a-b)*sx, (1-c)*sy);
	} else if (dir == "up") {
		if (start) rect((p0[0]+b)*sx, (p0[1]+c)*sy, (1-a-b)*sx, (1-c)*sy);
		else rect((p0[0]+a)*sx, (p0[1]+c)*sy, (1-a-b)*sx, (1-c)*sy);
	} else if (dir == "left") {
		if (start) rect((p0[0]+c)*sx, (p0[1]+a)*sy, (1-c)*sx, (1-a-b)*sy);
		else rect((p0[0]+c)*sx, (p0[1]+b)*sy, (1-c)*sx, (1-a-b)*sy);
	} else {
		if (start) rect(p0[0]*sx, (p0[1]+b)*sy, (1-c)*sx, (1-a-b)*sy);
		else rect(p0[0]*sx, (p0[1]+a)*sy, (1-c)*sx, (1-a-b)*sy);
	}
}

function drawPathPortion(path, k, x0, y0, w, h, m, n, lineCol, a, b, c) {
	push();
  translate(x0, y0);

	let sx = w/m, sy = h/n;

	noStroke();
	fill(lineCol);
	if (k == 0) {
  	drawExtremity(path, true, sx, sy, a, b, c);
	} else if (k == path.length-1) {
		drawExtremity(path, false, sx, sy, a, b, c);
	} else {
		var p0 = path[k-1];
    var p1 = path[k];
    let p2 = path[k+1];
    let dir01 = getDirection(p0, p1);
    let dir12 = getDirection(p1, p2);

    if (dir01 == dir12) {
			noStroke();
			fill(lineCol);
			if (dir01 == "down") {
				rect((p1[0]+a)*sx, p1[1]*sy, (1-a-b)*sx, sy);
			} else if (dir01 == "up") {
				rect((p1[0]+b)*sx, p1[1]*sy, (1-a-b)*sx, sy);
			} else if (dir01 == "left") {
				rect(p1[0]*sx, (p1[1]+a)*sy, sx, (1-a-b)*sy);
			} else {
				rect(p1[0]*sx, (p1[1]+b)*sy, sx, (1-a-b)*sy);
			}
    } else {
			noFill();
			stroke(lineCol);
			strokeWeight(Math.max(0.1, Math.abs(Math.max(0.1, Math.abs(sx*(1-a-b))))));
			strokeCap(SQUARE);
			if (dir01 == "up" && dir12 == "right") {
				arc(p1[0]*sx, p1[1]*sy, (1-a+b)*sx, (1-a+b)*sy, 0, PI/2);
			} else if (dir01 == "left" && dir12 == "down") {
				arc(p1[0]*sx, p1[1]*sy, (1+a-b)*sx, (1+a-b)*sy, 0, PI/2);
			} else if (dir01 == "right" && dir12 == "down") {
				arc((p1[0]+1)*sx, p1[1]*sy, (1-a+b)*sx, (1-a+b)*sy, PI/2, PI);
			} else if (dir01 == "up" && dir12 == "left") {
				arc((p1[0]+1)*sx, p1[1]*sy, (1+a-b)*sx, (1+a-b)*sy, PI/2, PI);
			} else if (dir01 == "down" && dir12 == "left") {
				arc((p1[0]+1)*sx, (p1[1]+1)*sy, (1-a+b)*sx, (1-a+b)*sy, PI, 3*PI/2);
			} else if (dir01 == "right" && dir12 == "up") {
				arc((p1[0]+1)*sx, (p1[1]+1)*sy, (1+a-b)*sx, (1+a-b)*sy, PI, 3*PI/2);
			} else if (dir01 == "left" && dir12 == "up") {
				arc(p1[0]*sx, (p1[1]+1)*sy, (1-a+b)*sx, (1-a+b)*sy, 3*PI/2, TAU);
			} else {
				arc(p1[0]*sx, (p1[1]+1)*sy, (1+a-b)*sx, (1+a-b)*sy, 3*PI/2, TAU);
			}
		}
	}

	pop();
}

